/** Module key (`std:NAME`) → that std module's source. */
export const STD_SOURCES: Record<string, string> = {
  "std:array": "// `std:array` — pure-VL array/list helpers over the intrinsic floor (the emitter\n// provides the list primitives `.push` / `.length` / indexing / `map` / `filter`;\n// these derived methods are written in VL on top of them, the array dual of\n// `std:fmt`). Each takes a `self` first parameter, so it reads as a UFCS method on\n// the receiver (`xs.indexOf(3)`, `xs.includes(3)`). All are GENERIC in the element\n// type `T`, so one definition serves `i32[]`, `string[]`, … — `==` resolves per\n// element type.\n//\n// The first group is the SEARCH family (each returns an i32 / boolean, building no\n// new collection); the second is the BUILDING family (`reverse` / `concat` /\n// `mapIndexed`, each returning a NEW list). The building family is GENERIC over the\n// element type too: a generic `const out: T[] = []` followed by `out.push(…)` now\n// propagates `T` through monomorphization, so one definition builds the right list\n// per instantiation. (`slice` and the bare `map`/`filter` are emitter primitives;\n// these add what the floor does not cover.)\n\n// The index of the FIRST element equal to `needle`, or -1 if absent. `==` is the\n// element type's equality (value for scalars / strings, reference for functions).\nexport function indexOf<T>(self: T[], needle: T): i32 {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return i }\n    i = i + 1\n  }\n  return -1\n}\n\n// The index of the LAST element equal to `needle`, or -1 if absent.\nexport function lastIndexOf<T>(self: T[], needle: T): i32 {\n  let i = self.length - 1\n  while i >= 0 {\n    if self[i] == needle { return i }\n    i = i - 1\n  }\n  return -1\n}\n\n// Whether any element equals `needle`.\nexport function includes<T>(self: T[], needle: T): boolean {\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { return true }\n    i = i + 1\n  }\n  return false\n}\n\n// How many elements equal `needle`.\nexport function count<T>(self: T[], needle: T): i32 {\n  let c = 0\n  let i = 0\n  while i < self.length {\n    if self[i] == needle { c = c + 1 }\n    i = i + 1\n  }\n  return c\n}\n\n// Left fold: thread `acc` (seeded with `init`) through `f(acc, element)` for each\n// element in order, returning the final accumulator. The accumulator type `A` may\n// differ from the element type `T` (summing an `i32[]` to an `i32`, joining a\n// `string[]` to a `string`, summing an `f64[]` to an `f64`). The generic closure\n// parameter `f: (A, T) => A` is monomorphized per call shape.\nexport function reduce<T, A>(self: T[], f: (A, T) => A, init: A): A {\n  let acc = init\n  let i = 0\n  while i < self.length {\n    acc = f(acc, self[i])\n    i = i + 1\n  }\n  return acc\n}\n\n// ── The BUILDING family — each returns a NEW list, leaving its inputs unmutated. ──\n\n// `self`'s elements in reverse order.\nexport function reverse<T>(self: T[]): T[] {\n  const out: T[] = []\n  let i = self.length - 1\n  while i >= 0 {\n    out.push(self[i])\n    i = i - 1\n  }\n  return out\n}\n\n// `self` followed by `other`. The element type `T` must match (`==`-comparable not\n// required — this only moves elements), so a mixed-type concat does not type-check.\nexport function concat<T>(self: T[], other: T[]): T[] {\n  const out: T[] = []\n  let i = 0\n  while i < self.length {\n    out.push(self[i])\n    i = i + 1\n  }\n  let j = 0\n  while j < other.length {\n    out.push(other[j])\n    j = j + 1\n  }\n  return out\n}\n\n// `map` with the element INDEX: `f(element, i)` for each element, collected in\n// order into a new list. The result element type `U` may differ from `T`. The\n// emitter's bare `.map` passes only the element; this is the indexed companion.\nexport function mapIndexed<T, U>(self: T[], f: (T, i32) => U): U[] {\n  const out: U[] = []\n  let i = 0\n  while i < self.length {\n    out.push(f(self[i], i))\n    i = i + 1\n  }\n  return out\n}\n",
  "std:buffer": "// `std:buffer` — the linear-memory tier's allocator and access surface, in pure\n// VL over the `__load_*__` / `__store_*__` / `__memory_*__` intrinsic floor\n// (`docs/internals/buffer-design.md` §C, sequencing item S5). The compiler owns\n// exactly what an INSTRUCTION is; allocation POLICY is ordinary code and lives\n// here (O1 = (c): `Buffer` is std VL, not a compiler-known type).\n//\n// TWO HEAPS. A `Buf` VALUE is an ordinary WasmGC struct with ordinary VL value\n// semantics; a `Buf`'s CONTENTS live in linear memory, which the host can read\n// directly through the module's exported `memory`. `.length` is a plain field\n// read — no call, no side table.\n//\n// BOUNDS: there are none here, by design (§A4). An access past the end of the\n// memory traps in the ENGINE — that trap is the memory-safety proof, and adding\n// a VL-level check would only make it quieter. An access past the end of a\n// `Buf` but still inside the memory is NOT caught: `Buf` describes an extent,\n// it does not fence it.\n//\n// HOST CONTRACT (O5 = lazy growth, no epoch export). `Buffer(n)` grows the\n// memory when it must, and a `memory.grow` DETACHES every host view of\n// `exports.memory.buffer`. A host must therefore re-take its typed-array views\n// after any guest call that may allocate; a stale view is detectable by\n// `view.byteLength === 0` (a detached view yields `undefined` on an indexed\n// read rather than throwing). This is what Emscripten's `updateMemoryViews()`,\n// wasm-bindgen's `byteLength === 0` probe and Go's `wasm_exec.js` buffer-\n// identity check all do; none of them exports a growth counter, and neither\n// does this module.\n//\n// RECLAMATION IS MARK/RELEASE, AND IT CAN DANGLE (O6). There is no per-object\n// `free`; `bufferMark()` / `bufferRelease(mark)` move the one bump pointer, so\n// reclamation is LIFO and costs nothing. The hazard is stated here rather than\n// in a footnote because it is the FIRST way a VL program can hold a dangling\n// reference at all: a `Buf` held across a `bufferRelease` that undoes its\n// allocation still points at live, in-bounds, since-reused linear memory. Reads\n// through it return another buffer's bytes and writes through it corrupt them —\n// SILENTLY. No trap fires, because nothing is out of bounds. Treat a released\n// mark as invalidating every `Buf` allocated after it.\n//\n// PERFORMANCE. Every access below is a real wasm `call`; `wasm-opt -O` (what\n// `vl build -O` runs) does NOT inline these wrappers, `-O3 --closed-world`\n// does (§O1). Every body is now ONE instruction plus its address arithmetic —\n// `store8`/`store16` were read-modify-write emulations and `fill`/`copyFrom`\n// were byte loops until the narrow-store and bulk intrinsics landed, and the\n// swap changed no signature and no expectation.\n\n// A `Buf` is a linear-memory extent: the byte address of its first byte, and\n// the number of bytes the caller ASKED for (the allocator may reserve a few\n// more for alignment; those are invisible here).\nexport type Buf = { base: i32, length: i32 }\n\n// A wasm page is 64 KiB; `__memory_size__` / `__memory_grow__` count pages.\nconst PAGE_SHIFT = 16\nconst PAGE_MASK = 65535\n\n// POLICY 1 — the reserved low region. Byte addresses below `HEAP_BASE` are\n// never handed out. Three reasons, none of them cosmetic:\n//   - address 0 stays outside every allocation, so `base == 0` cannot be a\n//     legitimate `Buf` and a zeroed/garbage descriptor is distinguishable;\n//   - a program may still poke raw addresses through the bare intrinsics\n//     (that is the §A3 \"two users collide\" hazard), and this leaves it a\n//     documented kilobyte that `std:buffer` promises never to touch;\n//   - the host's staging ABI probe (`ioMem`, `scripts/vl-host/src/main.rs`)\n//     wants a fixed low window it can own later without moving the heap.\n// 1 KiB, not one page: reserving a whole page would force a `memory.grow`\n// during init for programs that fit comfortably in the default one.\nconst HEAP_BASE = 1024\n\n// POLICY 2 — alignment. Every allocation's SIZE is rounded up to 8 bytes, and\n// `HEAP_BASE` is a multiple of 8, so every `Buf` starts 8-byte aligned and each\n// width's natural alignment is satisfied at offset 0 and at every 8-multiple\n// offset. This is a PERFORMANCE choice, not a correctness one — wasm's\n// alignment immediate is a hint and every load/store here is legal at any\n// address (pinned by the unaligned cases in `tests/cases/memory/`). 8 is the\n// widest scalar VL can store (i64 / f64).\nconst ALIGN = 8\n\n// The bump pointer: the address one past the last byte handed out. Module-level\n// mutable state, which is exactly what makes the allocator's policy ordinary\n// VL code (§C4).\nlet bumpPtr = HEAP_BASE\n\n// `n` rounded up to the next multiple of `ALIGN`.\nfunction alignUp(n: i32): i32 {\n  const slack = n & (ALIGN - 1)\n  if slack == 0 { return n }\n  return n + (ALIGN - slack)\n}\n\n// Grow the memory until byte `end` (exclusive) is addressable. Page arithmetic\n// throughout — computing `pages * 65536` would itself overflow i32 at 2 GiB,\n// which is inside the range this can be asked about.\nfunction ensureCapacity(end: i32) {\n  let needPages = end >> PAGE_SHIFT\n  if (end & PAGE_MASK) != 0 { needPages = needPages + 1 }\n  const havePages = __memory_size__()\n  if needPages > havePages {\n    // `memory.grow` answers with the size BEFORE the growth, or -1 on failure.\n    // A refused allocation cannot be papered over — the caller is about to write\n    // through a `Buf` that has no memory behind it.\n    //\n    // MEASURED, this branch is defensive rather than routine: `Buffer`'s i32\n    // overflow guard caps `end` at 2^31, i.e. at most 32768 pages, and wasm32's\n    // own ceiling is 65536 — so the SPEC limit is unreachable from here and only\n    // host resource exhaustion can produce the -1. Both hosts grow a 2 GiB\n    // request without complaint (wasmtime 47 and V8 alike, measured), which is\n    // why no corpus fixture pins this line: there is no request that fails\n    // deterministically on every host.\n    if __memory_grow__(needPages - havePages) < 0 { __trap__() }\n  }\n}\n\n// `Buffer(n)` — reserve `n` zero-filled bytes and describe them.\n//\n// ZERO-FILL: a wasm memory starts zeroed and freshly grown pages are zeroed, so\n// bytes that have never been handed out before are zero for free — no fill loop\n// runs here. That guarantee ends at the first `bufferRelease`: addresses handed\n// out a SECOND time carry whatever the previous owner wrote. Call\n// `buf.fill(0, buf.length, 0)` when reusing a released region and zeros matter.\n//\n// Traps on a negative length and on an allocation that would carry the bump\n// pointer past 2 GiB (where an i32 byte address stops being orderable), because\n// either would silently corrupt every later allocation.\nexport function Buffer(byteLength: i32): Buf {\n  if byteLength < 0 { __trap__() }\n  const base = bumpPtr\n  const next = base + alignUp(byteLength)\n  if next < base { __trap__() }\n  ensureCapacity(next)\n  bumpPtr = next\n  return { base: base, length: byteLength }\n}\n\n// `bufferMark()` — the current bump pointer, to hand back to `bufferRelease`.\nexport function bufferMark(): i32 { return bumpPtr }\n\n// `bufferRelease(mark)` — reclaim everything allocated since `mark` in one\n// move. LIFO, no free list, no fragmentation, and NO liveness check: see this\n// module's header for the dangling-`Buf` hazard this opens, which is silent\n// corruption rather than a trap.\n//\n// Traps on a mark outside `[HEAP_BASE, bumpPtr]` — below the base it would let\n// allocations walk into the reserved region, above the pointer it re-reserves\n// bytes that are already free. Both are bugs at the call site, not recoverable\n// states.\nexport function bufferRelease(mark: i32) {\n  if mark < HEAP_BASE { __trap__() }\n  if mark > bumpPtr { __trap__() }\n  bumpPtr = mark\n}\n\n// ── Loads: eight widths, four of them signed/unsigned pairs. ──\n//\n// The signed/unsigned split is REAL here and is kept: `i32.load8_s` and\n// `i32.load8_u` are two different instructions, and of the byte 0xFF the first\n// answers -1 while the second answers 255. (The stores below have no such\n// split — see `store8`.)\n\n// The byte at `off`, sign-extended into an i32 (0xFF → -1).\nexport function loadI8(self: Buf, off: i32): i32 {\n  return __load_i8__(self.base + off)\n}\n\n// The byte at `off`, zero-extended into an i32 (0xFF → 255).\nexport function loadU8(self: Buf, off: i32): i32 {\n  return __load_u8__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, sign-extended (0xFFFF → -1).\nexport function loadI16(self: Buf, off: i32): i32 {\n  return __load_i16__(self.base + off)\n}\n\n// The 16-bit halfword at `off`, zero-extended (0xFFFF → 65535).\nexport function loadU16(self: Buf, off: i32): i32 {\n  return __load_u16__(self.base + off)\n}\n\n// The 32-bit word at `off`.\nexport function loadI32(self: Buf, off: i32): i32 {\n  return __load_i32__(self.base + off)\n}\n\n// The 64-bit word at `off`.\nexport function loadI64(self: Buf, off: i32): i64 {\n  return __load_i64__(self.base + off)\n}\n\n// The 32-bit float at `off`.\nexport function loadF32(self: Buf, off: i32): f32 {\n  return __load_f32__(self.base + off)\n}\n\n// The 64-bit float at `off`.\nexport function loadF64(self: Buf, off: i32): f64 {\n  return __load_f64__(self.base + off)\n}\n\n// ── Stores: six widths, and no signed/unsigned split (O2). ──\n//\n// A store is sign-AGNOSTIC. There is exactly one instruction per width and it\n// TRUNCATES — `i32.store8` cannot tell a signed byte from an unsigned one — so\n// naming these `storeU8`/`storeI8` would falsely imply a signed twin exists.\n// Hence `store8` / `store16` against the loads' `loadI8` / `loadU8`: the\n// asymmetry is the instruction set's, and it is deliberate.\n\n// The 32-bit word at `off`.\nexport function storeI32(self: Buf, off: i32, v: i32) {\n  __store_i32__(self.base + off, v)\n}\n\n// The 64-bit word at `off`.\nexport function storeI64(self: Buf, off: i32, v: i64) {\n  __store_i64__(self.base + off, v)\n}\n\n// The 32-bit float at `off`.\nexport function storeF32(self: Buf, off: i32, v: f32) {\n  __store_f32__(self.base + off, v)\n}\n\n// The 64-bit float at `off`.\nexport function storeF64(self: Buf, off: i32, v: f64) {\n  __store_f64__(self.base + off, v)\n}\n\n// The low 8 bits of `v` at `off`. Higher bits are discarded, exactly as\n// `i32.store8` discards them — because this IS `i32.store8` (0x3a).\n//\n// This body used to be a READ-MODIFY-WRITE over the containing 32-bit word, and\n// its whole expectation set survived the swap unchanged, which is the evidence\n// that the emulation was faithful. What the emulation could not preserve was the\n// access WIDTH — it touched 4 bytes where the instruction touches 1 — and that\n// difference was unobservable from VL (no threads, no shared memory) but NOT\n// from the host: `tests/vl_exported_memory_test.ts` reads the untouched\n// neighbours through the exported memory, which is the assertion the emulation\n// would have failed.\nexport function store8(self: Buf, off: i32, v: i32) {\n  __store_i8__(self.base + off, v)\n}\n\n// The low 16 bits of `v` at `off`, little-endian — `i32.store16` (0x3b).\n//\n// This was two byte-wide read-modify-writes rather than one word-level one,\n// because a halfword at an address congruent to 3 mod 4 STRADDLES two words. The\n// instruction has no such difficulty: wasm's alignment immediate is a hint, and\n// a 16-bit store is legal and correct at every address, straddle included.\nexport function store16(self: Buf, off: i32, v: i32) {\n  __store_i16__(self.base + off, v)\n}\n\n// ── Bulk ops: one instruction each. ──\n//\n// THE ONE PLACE THIS MODULE DOES NOT PASS ITS ARGUMENT STRAIGHT THROUGH. Both\n// instructions take an UNSIGNED byte count, and VL has no unsigned i32, so a\n// negative `len` is ~4 GiB and traps in the engine. The byte loops these bodies\n// replaced treated a non-positive `len` as \"write nothing\", and that behaviour\n// is pinned (`tests/cases/std/buffer-bulk.vl`), so the guard stays. Which is the\n// right layering anyway: the intrinsic IS the instruction (`__memory_fill__`\n// traps on -5, pinned by `tests/cases/memory/bulk-negative-length-traps.vl`),\n// and softening it is POLICY, which is std's job (O1 = (c)).\n//\n// Nothing else is guarded. There is still no per-access bounds check — a range\n// that leaves the memory traps in the engine, and a range that leaves the `Buf`\n// but stays inside the memory is not caught, exactly as for every load and store\n// above. `Buf` describes an extent; it does not fence it.\n\n// Set `len` bytes starting at `off` to the low 8 bits of `byte` — `memory.fill`\n// (0xfc 11). A non-positive `len` writes nothing.\n// (Spelled as a positive `if` rather than an early `return`: a BARE `return` in a\n// void function type-checks and then fails at emit — `emitProgram: bare return is\n// not supported`. Worth knowing before reaching for a guard clause here.)\nexport function fill(self: Buf, off: i32, len: i32, byte: i32) {\n  if len > 0 { __memory_fill__(self.base + off, byte, len) }\n}\n\n// Copy `len` bytes from `src` at `srcOff` into `self` at `dstOff` — the\n// DESTINATION is the receiver (O3), matching `dst.fill(...)` and the\n// self-first UFCS shape `std:array` / `std:fmt` already establish. (`Buffer.copy`\n// is not spellable: VL has no static methods.)\n//\n// OVERLAP IS HANDLED, and it is now handled by the INSTRUCTION. `memory.copy`\n// (0xfc 10) is defined to behave as if the bytes went through a temporary —\n// memmove semantics, not memcpy — so an overlapping copy never reads a byte it\n// has already overwritten, in either direction. `self` and `src` may be the same\n// `Buf`, and may overlap partially either way.\n//\n// This body used to CHOOSE its loop direction from the absolute addresses,\n// because a naive forward loop is wrong exactly when the destination is above\n// the source. That choice is gone, not merely optimized: both directions were\n// pinned by value in `buffer-bulk.vl` before the swap and both still pass, which\n// is what makes \"the instruction has the semantics the loop was imitating\" a\n// measurement rather than a claim about the spec.\nexport function copyFrom(\n  self: Buf,\n  dstOff: i32,\n  src: Buf,\n  srcOff: i32,\n  len: i32,\n) {\n  if len > 0 { __memory_copy__(self.base + dstOff, src.base + srcOff, len) }\n}\n\n// ── Typed views (webcraft P1.1) ──────────────────────────────────────────────\n//\n// A VIEW is a `Buf` sub-range re-described in ELEMENTS rather than bytes: a byte\n// address plus an element COUNT, with an element width baked into the type. The\n// kernel it exists for is structure-of-arrays — `for i { x[i] += vx[i] }` over\n// columns — where the alternative is `loadF32(base + (i << 2))` spelled by hand\n// at every access, which is the DataView experience webcraft already has and\n// wants absorbed.\n//\n// WHY THE BASE FIELD CARRIES THE WIDTH IN ITS NAME (`f32base`, not `base`).\n// This is the one surprising thing in this section, and it is forced. VL is\n// STRUCTURALLY typed: `type X = {…}` is an alias for a shape, not a new nominal\n// identity, so two declarations with the same field names and types ARE THE SAME\n// TYPE and are silently interchangeable. Spelled the obvious way — both views as\n// `{ base: i32, length: i32 }` — an `I32View` would satisfy every `F32View`\n// parameter in this module, and `iv.getF32(0)` would type-check and REINTERPRET\n// the bits with no diagnostic. Measured, not feared: with both spelled `{base,\n// length}` a value built as one view type flows into the other's accessor and\n// prints the reinterpreted float. Distinct field NAMES are what make the two\n// types distinct to a structural checker, so the discriminator is spelled where\n// the checker can see it. A nominal newtype (webcraft P1.5) would let both go\n// back to `base`; until then this is the type safety, not a decoration.\n//\n// `.length` is the ELEMENT count, per the P1.1 spec's `x.length`. It is a plain\n// struct field — no call, no side table, exactly as `Buf.length` is.\n//\n// BOUNDS ARE CHECKED HERE, AND THIS IS THE ONE PLACE IN `std:buffer` THAT\n// CHECKS. Everything above obeys §A4 (the engine traps; a `Buf` describes an\n// extent and does not fence it). A view is different, and deliberately so,\n// because the P1.1 spec asks for it in the same breath as the surface:\n// \"index-bounds = count\". The reason the answer differs is that the FAILURE\n// MODE differs. An out-of-range byte offset on a `Buf` is usually far out and\n// leaves the memory, so the engine catches it. An out-of-range ELEMENT index on\n// a view is usually one or two past the end of a column — still inside the\n// memory, still inside some other column — so the engine sees nothing wrong and\n// the read returns A NEIGHBOUR'S BYTES. That is a silent wrong answer in exactly\n// the code (SoA kernels, snapshot/rollback, the differential harness) whose\n// entire value is being byte-comparable with a TS twin. So each accessor traps\n// on an index outside `[0, length)` via `__trap__` (`unreachable`) — the same\n// loud, deterministic, unrecoverable stop the engine's own bounds trap is.\n//\n// The check is TWO compares per access and is NOT hoisted out of a loop by\n// anything in VL (P1.4 asks that the policy be stated, not that it be\n// eliminated). `docs/internals/buffer-design.md` §L carries the measured cost\n// and the recipe for the unchecked spelling when a kernel has proved its own\n// bounds: `Buf`'s `loadF32`/`storeF32` are still there, still unfenced, and\n// still take a byte offset.\n\n// The largest element count whose byte size fits in a positive i32, per width.\n// `count << 2` at 2^29 is already negative, so the count must be rejected BEFORE\n// the shift rather than after it.\nconst MAX_COUNT_4 = 536870911\n\n// A view of 4-byte floats. `f32base` is the byte address of element 0; `length`\n// is the element count. See this section's header for why the field is not\n// called `base`.\nexport type F32View = { f32base: i32, length: i32 }\n\n// A view of 4-byte signed integers.\nexport type I32View = { i32base: i32, length: i32 }\n\n// Shared construction check for a 4-byte-element view over `self`: `off` is a\n// BYTE offset into the `Buf` and `count` is an ELEMENT count. Traps unless the\n// whole range `[off, off + count*4)` lies inside the `Buf`.\n//\n// This is the ALLOCATION-TIME check §J3 puts in std's hands, taken once per view\n// rather than once per access. It is what makes the per-access check able to be\n// just `0 <= i < length`: if the extent was validated when the view was made,\n// an in-range index cannot leave the `Buf`.\n//\n// A view may be EMPTY (`count == 0`), which is in-range for every offset up to\n// `length` and satisfies no index at all — the natural base case for a loop over\n// a column that happens to have no rows.\nfunction view4Base(self: Buf, off: i32, count: i32): i32 {\n  if off < 0 { __trap__() }\n  if count < 0 { __trap__() }\n  if count > MAX_COUNT_4 { __trap__() }\n  const bytes = count << 2\n  const end = off + bytes\n  if end < off { __trap__() }\n  if end > self.length { __trap__() }\n  return self.base + off\n}\n\n// `buf.f32view(off, count)` — `count` f32 elements starting at byte `off`.\nexport function f32view(self: Buf, off: i32, count: i32): F32View {\n  const b = view4Base(self, off, count)\n  return { f32base: b, length: count }\n}\n\n// `buf.i32view(off, count)` — `count` i32 elements starting at byte `off`.\nexport function i32view(self: Buf, off: i32, count: i32): I32View {\n  const b = view4Base(self, off, count)\n  return { i32base: b, length: count }\n}\n\n// Element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function getF32(self: F32View, i: i32): f32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_f32__(self.f32base + (i << 2))\n}\n\n// Write element `i` of an f32 view. Traps on an index outside `[0, length)`.\nexport function setF32(self: F32View, i: i32, v: f32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_f32__(self.f32base + (i << 2), v)\n}\n\n// Element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function getI32(self: I32View, i: i32): i32 {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  return __load_i32__(self.i32base + (i << 2))\n}\n\n// Write element `i` of an i32 view. Traps on an index outside `[0, length)`.\nexport function setI32(self: I32View, i: i32, v: i32) {\n  if i < 0 { __trap__() }\n  if i >= self.length { __trap__() }\n  __store_i32__(self.i32base + (i << 2), v)\n}\n\n// The byte offset of element `i` RELATIVE TO the `Buf` the view was cut from is\n// not recoverable from the view alone (a view knows an absolute address, not its\n// parent). These two return the ABSOLUTE byte address of element `i`, which is\n// what a caller mixing view access with the bare intrinsics or with a host-side\n// typed array needs. No bounds check: this computes an address, it does not\n// dereference one, and `byteAddrF32(v, v.length)` — the one-past-the-end address\n// — is the useful answer for a range, not an error.\nexport function byteAddrF32(self: F32View, i: i32): i32 {\n  return self.f32base + (i << 2)\n}\n\nexport function byteAddrI32(self: I32View, i: i32): i32 {\n  return self.i32base + (i << 2)\n}\n",
  "std:fmt": "// `std:fmt` — pure-VL formatting helpers over the intrinsic floor\n// (docs/std-design.md D4 item 1). Imports nothing: strings are built with\n// `+`/`.slice` and rendered digit by digit. The exported helpers take a\n// `self` first parameter, so they read as UFCS methods on the receiver\n// (`n.toStr()`, `parts.join(sep)`). f64→string (shortest round-trip,\n// Ryu-class) is deliberately absent — `print` keeps covering floats.\n\n// Decimal digit d in 0..=9 as its character. Takes i64 so both integer\n// widths share one renderer (i64 cannot narrow to i32, so a string-index\n// lookup is not expressible for the wide path).\nfunction digitChar(d: i64) {\n  if d == 0 { return \"0\" }\n  if d == 1 { return \"1\" }\n  if d == 2 { return \"2\" }\n  if d == 3 { return \"3\" }\n  if d == 4 { return \"4\" }\n  if d == 5 { return \"5\" }\n  if d == 6 { return \"6\" }\n  if d == 7 { return \"7\" }\n  if d == 8 { return \"8\" }\n  \"9\"\n}\n\n// Decimal rendering of any i64, including i64 min. The accumulator works in\n// the NEGATIVE range (positive inputs are negated first) because the negative\n// range covers i64 min, whose magnitude overflows when negated; `%` on a\n// negative operand yields a digit in -9..=0, negated back per digit.\nfunction renderI64(n: i64) {\n  if n == 0 { return \"0\" }\n  const zero: i64 = 0\n  let m = n\n  if m > 0 { m = zero - m }\n  let out = \"\"\n  while m < 0 {\n    out = digitChar(zero - (m % 10)) + out\n    m = m / 10\n  }\n  if n < 0 { out = \"-\" + out }\n  out\n}\n\n// Decimal rendering of an integer via its receiver: `n.toStr()` over an i32\n// or i64 binding. One union receiver covers both widths (UFCS resolves by\n// `self`+arity; the value boxes in, `is`-narrows out); i32 widens losslessly\n// into the shared i64 renderer. The boolean arm renders true/false.\nexport function toStr(self: i32 | i64 | boolean) {\n  if self is boolean {\n    if self { return \"true\" }\n    return \"false\"\n  }\n  if self is i32 {\n    const wide: i64 = self\n    return renderI64(wide)\n  }\n  return renderI64(self)\n}\n\n// `self` concatenated n times; n <= 0 yields \"\".\nexport function repeat(self: string, n: i32) {\n  let out = \"\"\n  let i = 0\n  while i < n {\n    out = out + self\n    i = i + 1\n  }\n  out\n}\n\n// Pads `self` on the left with `fill` up to `width`. A multi-codepoint fill is\n// tiled and truncated so the result is exactly `width` long; returns `self`\n// unchanged when it is already wide enough or when fill is empty.\nexport function padLeft(self: string, width: i32, fill: string) {\n  if fill.length == 0 { return self }\n  const deficit = width - self.length\n  if deficit <= 0 { return self }\n  let pad = \"\"\n  let have = 0\n  while have < deficit {\n    pad = pad + fill\n    have = have + fill.length\n  }\n  return pad.slice(0, deficit) + self\n}\n\n// Elements of `self` concatenated with `sep` between consecutive elements.\nexport function join(self: string[], sep: string) {\n  let out = \"\"\n  let i = 0\n  while i < self.length {\n    if i > 0 { out = out + sep }\n    out = out + self[i]\n    i = i + 1\n  }\n  out\n}\n\n// Splits `self` into the substrings between each (non-overlapping, left-to-right)\n// occurrence of `sep`. An empty `sep` splits into individual characters; a `sep`\n// longer than the remaining text leaves the whole remainder as the final segment.\n// `\"a,b,c\".split(\",\")` → [\"a\", \"b\", \"c\"]; `\"\".split(\",\")` → [\"\"].\nexport function split(self: string, sep: string): string[] {\n  const out: string[] = []\n  if sep.length == 0 {\n    let i = 0\n    while i < self.length {\n      out.push(self.slice(i, i + 1))\n      i = i + 1\n    }\n    return out\n  }\n  let start = 0\n  let i = 0\n  while i <= self.length - sep.length {\n    if self.slice(i, i + sep.length) == sep {\n      out.push(self.slice(start, i))\n      i = i + sep.length\n      start = i\n    } else {\n      i = i + 1\n    }\n  }\n  out.push(self.slice(start, self.length))\n  return out\n}\n",
  "std:seed": "// `std:seed` — a trivial module whose only job is to prove the `std:`\n// resolution plumbing end to end (both resolvers, the Rust host's std-dir\n// mapping, the CLI's fsRead wrap, the LSP's embedded map). Real std content\n// (`std:fmt`, `std:test`, collections) lands in later slices\n// (docs/std-design.md D4); this file can be retired once any of them exists.\nexport function stdSmoke() { return 7 }\n",
  "std:test": "// `std:test` v1 — a pure-VL assertion library over the intrinsic floor\n// (docs/std-design.md D5). The matcher surface reads jest-shaped through\n// STRUCT-RECEIVER UFCS: `expect(x).toEqual(y)` builds an `Expectation` and\n// `.toEqual` is a free `self`-function resolved by self+arity. A failed\n// assertion calls `__trap__()` (jest's \"a test stops at its first failed\n// expectation\"); a passing one is a no-op. Under bare `vl run` a green file\n// exits 0 and a red one aborts; the runner half (`vl test`, per-test trap\n// isolation, reporting — docs/test-runner-design.md) drives these from the host.\n//\n// `expect` takes a VALUE UNION over the comparable atoms, so ONE entry point\n// covers every value kind — the value boxes into the union and `is`-narrows\n// back out. (`toBe` referential identity is reserved for the future `===`,\n// ROADMAP A15; `toThrow`/`toBeNull` wait on the error model / `null` in the\n// value union — std-design OD6.)\ntype Expectation = {\n  actual: i32 | i64 | f64 | boolean | string,\n  negated: boolean\n}\n\n// `expect(value)` — the receiver for the matchers.\nexport function expect(value: i32 | i64 | f64 | boolean | string): Expectation {\n  return { actual: value, negated: false }\n}\n\n// Inverts the pass/fail sense: `expect(5).not().toEqual(6)` passes. Returns a\n// fresh `Expectation` (the receiver is a value; no aliasing).\nexport function not(self: Expectation): Expectation {\n  return { actual: self.actual, negated: !self.negated }\n}\n\n// Aborts unless `ok` agrees with the current sense (`negated`). Factored so\n// every matcher shares one pass/fail/`__trap__` decision. (No `: void`\n// annotation — an explicit `void` return is mis-lowered on the current seed;\n// the inferred void is correct.)\nfunction adjudicate(self: Expectation, ok: boolean) {\n  if self.negated {\n    if ok { __trap__() }\n  } else {\n    if !ok { __trap__() }\n  }\n}\n\n// `.toEqual` — structural equality, jest semantics. The union `==` compares the\n// two values' live variants (a cross-variant pair, `expect(4).toEqual(\"4\")`, is\n// unequal). `self.actual` binds to a local first: union `==` requires binding\n// operands, not a raw field read.\nexport function toEqual(\n  self: Expectation,\n  expected: i32 | i64 | f64 | boolean | string,\n) {\n  const a = self.actual\n  adjudicate(self, a == expected)\n}\n\n// `.toBeTrue` — the receiver holds boolean `true`. A non-boolean receiver is\n// never true (the `is` arm simply does not fire).\nexport function toBeTrue(self: Expectation) {\n  const a = self.actual\n  let ok = false\n  if a is boolean { ok = a }\n  adjudicate(self, ok)\n}\n\n// `.toBeFalse` — the receiver holds boolean `false`.\nexport function toBeFalse(self: Expectation) {\n  const a = self.actual\n  let ok = false\n  if a is boolean { ok = !a }\n  adjudicate(self, ok)\n}\n",
};
